<?php $pageTitle='Schedule paper'; ?>
<section class="page-heading"><div><p class="eyebrow"><?= e($cycle['name']) ?></p><h1>Schedule examination paper</h1><p>Choose the branch and semester first. Only subjects assigned to that curriculum will be available.</p></div><a class="secondary-button" href="<?= e(url('date-sheets/'.$cycle['id'])) ?>">Back to date sheet</a></section><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?><form class="record-form" method="post" action="<?= e(url('date-sheets/'.$cycle['id'].'/papers')) ?>"><?= csrf_field() ?><section class="panel form-section"><div class="form-section-heading"><p class="eyebrow">Paper</p><h2>Course and cohort</h2></div><div class="form-grid two"><label>Programme / branch<select name="programme_id" id="schedule-programme" required><option value="">Select programme first</option><?php foreach($programmes as $programme):?><option value="<?= (int)$programme['id'] ?>"><?= e($programme['code'].' - '.$programme['name']) ?></option><?php endforeach;?></select></label><label>Semester<select name="semester" id="schedule-semester" required><option value="">Select semester</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>">Semester <?= $i ?></option><?php endfor;?></select></label><label>Subject / course<select name="course_id" id="schedule-course" required disabled><option value="">Choose programme and semester</option><?php foreach($courses as $course):?><option value="<?= (int)$course['id'] ?>" data-programme="<?= (int)$course['programme_id'] ?>" data-semester="<?= (int)$course['semester'] ?>"><?= e($course['code'].' - '.$course['name']) ?></option><?php endforeach;?></select><small id="course-guidance">Subjects are loaded from the branch curriculum.</small></label><label>Display label<input name="display_label" placeholder="B.Tech. (CSE), 4th Semester"></label><label>Examination date<select name="exam_date" required><?php foreach($dates as $date):?><option value="<?= e($date) ?>"><?= e(date('l, d F Y',strtotime($date))) ?></option><?php endforeach;?></select></label><label>Shift<select name="shift_id" required><?php foreach($shifts as $shift):?><option value="<?= (int)$shift['id'] ?>"><?= e($shift['name'].' '.substr($shift['start_time'],0,5).'-'.substr($shift['end_time'],0,5)) ?></option><?php endforeach;?></select></label><label>Category<select name="category"><option value="regular">Regular</option><option value="repeat">Repeat</option><option value="back_paper">Back Paper</option><option value="special">Special</option><option value="pass_out">Pass-Out</option><option value="not_promoted">Not-Promoted</option></select></label></div></section><div class="form-actions"><a class="text-button" href="<?= e(url('date-sheets/'.$cycle['id'])) ?>">Cancel</a><button class="primary-button">Schedule and calculate eligibility</button></div></form>
<script>(()=>{const programme=document.getElementById('schedule-programme'),semester=document.getElementById('schedule-semester'),course=document.getElementById('schedule-course'),guidance=document.getElementById('course-guidance'),source=[...course.options].slice(1).map(option=>option.cloneNode(true));function sync(){const p=programme.value,s=semester.value;course.innerHTML='<option value="">Select curriculum subject</option>';const matches=source.filter(option=>option.dataset.programme===p&&option.dataset.semester===s);matches.forEach(option=>course.append(option.cloneNode(true)));course.disabled=!p||!s||matches.length===0;guidance.textContent=!p||!s?'Choose a programme and semester first.':matches.length?`${matches.length} curriculum subject${matches.length===1?'':'s'} available.`:'No subject is mapped here. Add it in Programme curriculum first.';}programme.addEventListener('change',sync);semester.addEventListener('change',sync);sync();})();</script>
